changeSet.sql:
DELETE FROM subscription_plan_features;
INSERT INTO subscription_plan_features (subscription_plan_id, features)
SELECT sp.id, f.feature
FROM subscription_plan sp,
     (VALUES
       ('PREVENTIVE_MAINTENANCE'), ('CHECKLIST'), ('FILE'), ('PURCHASE_ORDER'),
       ('METER'), ('REQUEST_CONFIGURATION'), ('ADDITIONAL_TIME'), ('ADDITIONAL_COST'),
       ('ANALYTICS'), ('REQUEST_PORTAL'), ('SIGNATURE'), ('ROLE'),
       ('WORKFLOW'), ('API_ACCESS'), ('WEBHOOK'), ('IMPORT_CSV')
     ) AS f(feature);
